def extra(lm, img, side, h, w):
    out = {}
    try:
        def pt(name):
            v = lm.get(name)
            if v is None:
                return None
            x, y = float(v[0]), float(v[1])
            if not (math.isfinite(x) and math.isfinite(y)):
                return None
            return (x, y)

        head = pt('head')
        ns = pt('neck_sup')
        ni = pt('neck_inf')
        st = pt('shaft_top')
        sb = pt('shaft_bot')
        gt_lat = pt('gt_lat')
        gt_top = pt('gt_top')
        lt_tip = pt('lt_tip')
        lt_up = pt('lt_up')
        lt_down = pt('lt_down')

        def row_width(cy, cx_hint, thresh_rel):
            y = int(round(cy))
            if y < 0 or y >= h:
                return None
            row = img[y]
            mx = 0.0
            for xx in range(w):
                v = float(row[xx])
                if v > mx:
                    mx = v
            if mx <= 1.0:
                return None
            thr = mx * thresh_rel
            cx = int(round(cx_hint))
            if cx < 0: cx = 0
            if cx >= w: cx = w - 1
            if float(row[cx]) < thr:
                found = -1
                for d in range(1, w):
                    if cx - d >= 0 and float(row[cx - d]) >= thr:
                        found = cx - d; break
                    if cx + d < w and float(row[cx + d]) >= thr:
                        found = cx + d; break
                if found < 0:
                    return None
                cx = found
            left = cx
            while left > 0 and float(row[left - 1]) >= thr:
                left -= 1
            right = cx
            while right < w - 1 and float(row[right + 1]) >= thr:
                right += 1
            return float(right - left + 1)

        def shaft_width_at(y_target):
            if st is None or sb is None:
                return None
            dy = sb[1] - st[1]
            t = 0.0
            if abs(dy) > 1e-3:
                t = (y_target - st[1]) / dy
                if t < 0.0: t = 0.0
                if t > 1.0: t = 1.0
            cx_shaft = st[0] + t * (sb[0] - st[0])
            return row_width(y_target, cx_shaft, 0.35)

        # 1) ширина костной полосы на уровне lt_tip к ширине диафиза
        if lt_tip is not None and st is not None and sb is not None:
            w_lt = row_width(lt_tip[1], lt_tip[0], 0.35)
            y_shaft = 0.5 * (st[1] + sb[1])
            w_sh = shaft_width_at(y_shaft)
            if w_lt is not None and w_sh is not None and w_sh > 1e-3:
                out['lt_row_w_over_shaft_w'] = float(w_lt / w_sh)

        # 2) относительное удлинение полосы на уровне lt_tip к полосе чуть выше (lt_up)
        if lt_tip is not None and lt_up is not None:
            w_lt = row_width(lt_tip[1], lt_tip[0], 0.35)
            w_up = row_width(lt_up[1], lt_up[0], 0.35)
            if w_lt is not None and w_up is not None and w_up > 1e-3:
                out['lt_row_w_over_up_w'] = float(w_lt / w_up)

        # 3) смещение gt_lat от линии head-neck_mid
        if head is not None and ns is not None and ni is not None and gt_lat is not None:
            mx = 0.5 * (ns[0] + ni[0])
            my = 0.5 * (ns[1] + ni[1])
            ax, ay = head[0], head[1]
            bx, by = mx, my
            dx, dy = bx - ax, by - ay
            L = math.hypot(dx, dy)
            neck_w = math.hypot(ns[0] - ni[0], ns[1] - ni[1])
            if L > 1e-3 and neck_w > 1e-3:
                px, py = gt_lat[0] - ax, gt_lat[1] - ay
                cross = abs(dx * py - dy * px) / L
                out['gt_off_neckline'] = float(cross / neck_w)

        # 4) выступание lt_tip за линию lt_up-lt_down, в долях ширины диафиза
        if lt_tip is not None and lt_up is not None and lt_down is not None:
            ax, ay = lt_up[0], lt_up[1]
            bx, by = lt_down[0], lt_down[1]
            dx, dy = bx - ax, by - ay
            L = math.hypot(dx, dy)
            if L > 1e-3:
                # расстояние от lt_tip до прямой lt_up-lt_down
                px, py = lt_tip[0] - ax, lt_tip[1] - ay
                cross = (dx * py - dy * px) / L
                dist = abs(cross)
                # ширина диафиза на уровне lt_tip
                w_sh = shaft_width_at(lt_tip[1])
                if w_sh is not None and w_sh > 1e-3:
                    out['lt_protrude_over_shaftw'] = float(dist / w_sh)

    except Exception:
        pass

    res = {}
    for k, v in out.items():
        if isinstance(v, float) and math.isfinite(v):
            res[k] = v
    return res

def extra(lm, img, side, h, w):
    out = {}
    try:
        def pt(name):
            v = lm.get(name)
            if v is None:
                return None
            x, y = float(v[0]), float(v[1])
            if not (math.isfinite(x) and math.isfinite(y)):
                return None
            return (x, y)

        head = pt('head')
        ns = pt('neck_sup')
        ni = pt('neck_inf')
        st = pt('shaft_top')
        sb = pt('shaft_bot')
        gt_lat = pt('gt_lat')
        gt_top = pt('gt_top')
        lt_tip = pt('lt_tip')
        lt_up = pt('lt_up')
        lt_down = pt('lt_down')

        def mean_bright(cx, cy, r):
            x0 = int(max(0, math.floor(cx - r)))
            x1 = int(min(w - 1, math.ceil(cx + r)))
            y0 = int(max(0, math.floor(cy - r)))
            y1 = int(min(h - 1, math.ceil(cy + r)))
            if x1 <= x0 or y1 <= y0:
                return None
            s = 0.0
            n = 0
            for yy in range(y0, y1 + 1):
                for xx in range(x0, x1 + 1):
                    v = float(img[yy, xx])
                    if v > 0.0:
                        s += v
                        n += 1
            if n < 4:
                return None
            return s / n

        def row_width(cy, cx_hint, thresh_rel):
            # ширина костной полосы в строке cy около cx_hint по порогу от максимума строки
            y = int(round(cy))
            if y < 0 or y >= h:
                return None
            row = img[y]
            mx = 0.0
            for xx in range(w):
                v = float(row[xx])
                if v > mx:
                    mx = v
            if mx <= 1.0:
                return None
            thr = mx * thresh_rel
            cx = int(round(cx_hint))
            if cx < 0: cx = 0
            if cx >= w: cx = w - 1
            # найти ближайший к cx пиксель выше порога
            if float(row[cx]) < thr:
                found = -1
                for d in range(1, w):
                    if cx - d >= 0 and float(row[cx - d]) >= thr:
                        found = cx - d; break
                    if cx + d < w and float(row[cx + d]) >= thr:
                        found = cx + d; break
                if found < 0:
                    return None
                cx = found
            left = cx
            while left > 0 and float(row[left - 1]) >= thr:
                left -= 1
            right = cx
            while right < w - 1 and float(row[right + 1]) >= thr:
                right += 1
            return float(right - left + 1)

        # 1) ширина костной полосы на уровне lt_tip к ширине диафиза
        if lt_tip is not None and st is not None and sb is not None:
            w_lt = row_width(lt_tip[1], lt_tip[0], 0.35)
            # ширина диафиза чуть ниже st и выше sb
            y_shaft = 0.5 * (st[1] + sb[1])
            # cx диафиза на этой высоте — интерполяция по x st..sb
            t = 0.0
            dy = sb[1] - st[1]
            if abs(dy) > 1e-3:
                t = (y_shaft - st[1]) / dy
                if t < 0.0: t = 0.0
                if t > 1.0: t = 1.0
            cx_shaft = st[0] + t * (sb[0] - st[0])
            w_sh = row_width(y_shaft, cx_shaft, 0.35)
            if w_lt is not None and w_sh is not None and w_sh > 1e-3:
                out['lt_row_w_over_shaft_w'] = float(w_lt / w_sh)

        # 2) относительное удлинение полосы на уровне lt_tip к полосе чуть выше (lt_up)
        if lt_tip is not None and lt_up is not None:
            w_lt = row_width(lt_tip[1], lt_tip[0], 0.35)
            w_up = row_width(lt_up[1], lt_up[0], 0.35)
            if w_lt is not None and w_up is not None and w_up > 1e-3:
                out['lt_row_w_over_up_w'] = float(w_lt / w_up)

        # 3) длина шейки к ширине шейки
        if head is not None and ns is not None and ni is not None:
            mx = 0.5 * (ns[0] + ni[0])
            my = 0.5 * (ns[1] + ni[1])
            neck_len = math.hypot(mx - head[0], my - head[1])
            neck_w = math.hypot(ns[0] - ni[0], ns[1] - ni[1])
            if neck_w > 1e-3:
                out['neck_len_over_neckw'] = float(neck_len / neck_w)

        # 4) смещение gt_lat от линии head-neck_mid
        if head is not None and ns is not None and ni is not None and gt_lat is not None:
            mx = 0.5 * (ns[0] + ni[0])
            my = 0.5 * (ns[1] + ni[1])
            ax, ay = head[0], head[1]
            bx, by = mx, my
            dx, dy = bx - ax, by - ay
            L = math.hypot(dx, dy)
            neck_w = math.hypot(ns[0] - ni[0], ns[1] - ni[1])
            if L > 1e-3 and neck_w > 1e-3:
                px, py = gt_lat[0] - ax, gt_lat[1] - ay
                cross = abs(dx * py - dy * px) / L
                out['gt_off_neckline'] = float(cross / neck_w)

    except Exception:
        pass

    res = {}
    for k, v in out.items():
        if isinstance(v, float) and math.isfinite(v):
            res[k] = v
    return res
